package com.aird;

import org.springframework.boot.ApplicationRunner;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.transaction.support.TransactionTemplate;
import java.nio.file.*;
import java.util.*;

@Configuration
public class Bootstrap {
    @Bean ApplicationRunner seed(Store s,FileStorage files,PasswordEncoder passwords,TransactionTemplate tx,
        @Value("${app.demo}") boolean demo,@Value("${app.mode}") String mode,@Value("${app.bootstrap.email}") String email,@Value("${app.bootstrap.password}") String password) {
        return args->{
            if(mode.equals("worker") || s.count("SELECT COUNT(*) FROM users")>0)return;
            if(!demo){Problem.require(!email.isBlank() && password.length()>=16,422,"First production startup requires ADMIN_EMAIL and ADMIN_PASSWORD (16+ characters).");s.insert("INSERT INTO users(name,email,password_hash,role,created_at) VALUES(?,?,?,?,?)","Administrator",email.toLowerCase(Locale.ROOT),passwords.encode(password),"admin",Store.now());return;}
            tx.executeWithoutResult(status->{
                long admin=s.insert("INSERT INTO users(name,email,password_hash,role,created_at) VALUES(?,?,?,?,?)","Alex Morgan","admin@aird.local",passwords.encode("AdminDemo!2026"),"admin",Store.now());
                long maya=s.insert("INSERT INTO users(name,email,password_hash,role,created_at) VALUES(?,?,?,?,?)","Maya Chen","maya@aird.local",passwords.encode("ResearchDemo!2026"),"researcher",Store.now());
                long jordan=s.insert("INSERT INTO users(name,email,password_hash,role,created_at) VALUES(?,?,?,?,?)","Jordan Lee","jordan@aird.local",passwords.encode("ResearchDemo!2026"),"researcher",Store.now());
                long compute=s.insert("INSERT INTO resources(name,type,capacity,created_at) VALUES(?,?,?,?)","CPU research worker","compute",1,Store.now());
                long storage=s.insert("INSERT INTO resources(name,type,capacity,created_at) VALUES(?,?,?,?)","Private dataset storage","storage",1024,Store.now());
                long p=s.insert("INSERT INTO projects(name,description,color,compute_resource_id,storage_resource_id,created_at) VALUES(?,?,?,?,?,?)","Customer intelligence","Understand customer behavior and build more reliable churn predictions.","#7662e8",compute,storage,Store.now());
                long p2=s.insert("INSERT INTO projects(name,description,color,compute_resource_id,storage_resource_id,created_at) VALUES(?,?,?,?,?,?)","Material discovery","A separate workspace for material property research and regression models.","#32a899",compute,storage,Store.now());
                s.db.update("INSERT INTO memberships(project_id,user_id) VALUES(?,?)",p,maya);s.db.update("INSERT INTO memberships(project_id,user_id) VALUES(?,?)",p2,jordan);
                var csv=new StringBuilder("tenure_months,monthly_spend,support_tickets,plan,churn\n");var random=new Random(42);
                for(int i=0;i<240;i++){int tenure=1+random.nextInt(60),tickets=random.nextInt(8);double spend=25+random.nextDouble()*100;String plan=random.nextBoolean()?"standard":"premium";double score=tickets*0.9-tenure*0.07+(plan.equals("premium")?-1:0)+random.nextGaussian()*1.2;csv.append(tenure).append(',').append(String.format(Locale.ROOT,"%.2f",spend)).append(',').append(tickets).append(',').append(plan).append(',').append(score>1.2?"yes":"no").append('\n');}
                try{
                    var temp=Files.createTempFile(files.root,"seed-",".tmp");Files.writeString(temp,csv.toString());String key=UUID.randomUUID()+".csv";var table=files.read(temp);long bytes=Files.size(temp);String checksum=files.checksum(temp);files.publish(temp,key);
                    long d=s.insert("INSERT INTO datasets(project_id,owner_id,name,description,source,license,created_at) VALUES(?,?,?,?,?,?,?)",p,maya,"Customer churn · demo fixture","240 synthetic customer records for exercising the complete training workflow.","Generated by Bootstrap.java with seed 42; synthetic, not real customer data.","CC0-1.0 (generated fixture)",Store.now());
                    long v=s.insert("INSERT INTO dataset_versions(dataset_id,version_number,object_key,checksum,bytes,row_count,column_count,schema_json,created_at) VALUES(?,1,?,?,?,?,?,?,?)",d,key,checksum,bytes,table.rows().size(),table.headers().size(),s.encode(files.summary(table)),Store.now());
                    long e=s.insert("INSERT INTO experiments(project_id,name,notes,tags,created_at) VALUES(?,?,?,?,?)",p,"Churn prediction baseline","Real models trained on a clearly labeled synthetic demo dataset.","baseline,classification",Store.now());
                    for(String model:List.of("logistic_regression","random_forest")){
                        long job=s.insert("INSERT INTO jobs(project_id,user_id,experiment_id,dataset_version_id,name,model,target_column,parameters_json,seed,test_fraction,submission_key,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",p,maya,e,v,model.equals("random_forest")?"Random forest exploration":"Logistic baseline",model,"churn","{}",42,0.2,"seed-"+model,Store.now());s.event(job,"queued","Demo fixture run queued for real Java model training.");
                    }
                    s.db.update("INSERT INTO comments(project_id,user_id,body,created_at) VALUES(?,?,?,?)",p,maya,"Starting with a reproducible baseline. Both runs use the same dataset version and seed so we can compare them.",Store.now());
                }catch(Exception ex){throw new IllegalStateException("Could not seed demo dataset.",ex);}
                s.audit(admin,"Initialized local demo workspace","project",p);
            });
        };
    }
}
